<?php $title='Pengaturan';require '_head.php';if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['site_name','logo','description','about_title','about','address','phone','whatsapp','email','instagram'] as $k)$pdo->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute([$k,$_POST[$k]??'']);$saved=true;}?><h1>Pengaturan</h1><div class="panel"><form method="post"><?php foreach(['site_name'=>'Nama website','logo'=>'Path logo','description'=>'Deskripsi singkat','about_title'=>'Judul tentang','about'=>'Tentang kami','address'=>'Alamat','phone'=>'Telepon','whatsapp'=>'WhatsApp (angka saja)','email'=>'Email','instagram'=>'Instagram'] as $k=>$label):?><label><?=e($label)?></label><?php if(in_array($k,['about','description'])):?><textarea name="<?=$k?>"><?=e(setting($k))?></textarea><?php else:?><input name="<?=$k?>" value="<?=e(setting($k))?>"><?php endif;endforeach;?><button>Simpan Pengaturan</button></form></div><?php require '_foot.php';?>